package com.fooddelivery.order.entity;import javax.persistence.*;import java.time.*;@Entity @Table(name="orders")public class CustomerOrder{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;private Long userId;private String restaurantId;private String itemsJson;private double totalAmount;private String status;private LocalDateTime createdAt=LocalDateTime.now();public Long getId(){return id;}public Long getUserId(){return userId;}public void setUserId(Long v){userId=v;}public String getRestaurantId(){return restaurantId;}public void setRestaurantId(String v){restaurantId=v;}public String getItemsJson(){return itemsJson;}public void setItemsJson(String v){itemsJson=v;}public double getTotalAmount(){return totalAmount;}public void setTotalAmount(double v){totalAmount=v;}public String getStatus(){return status;}public void setStatus(String v){status=v;}public LocalDateTime getCreatedAt(){return createdAt;}}
